      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    .brand__mark {
      display: inline-grid;
      place-items: center;
      width: 2.4rem;
      height: 2.4rem;
      border: 1px solid var(--border-strong);
      border-radius: 50%;
      background: linear-gradient(135deg, rgba(229, 196, 118, 0.25), rgba(255, 255, 255, 0.04));
      box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.04);
    }

    .brand__mark span {
      color: var(--accent);
      font-size: 1rem;
    }

    .top-nav ul,
    .footer-nav ul,
    .hero-stats,
    .card-grid,
    .editorial-grid,
    .deal-list,
    .pill-list {
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .top-nav ul {
      display: flex;
      flex-wrap: wrap;
      gap: 0.35rem;
      justify-content: flex-end;
    }

    .top-nav a {
      display: inline-block;
      padding: 0.65rem 0.9rem;
      color: var(--muted);
      border-radius: 999px;
    }

    .top-nav a[aria-current="page"],
    .top-nav a:hover {
      color: var(--text);
      background: rgba(255, 255, 255, 0.06);
      text-decoration: none;
    }

    main {
      padding: 2rem 0 4rem;
    }

    .section {
      margin-top: 2rem;
    }

    .hero {
      position: relative;
      overflow: clip;
      padding: clamp(1.5rem, 3vw, 2.5rem);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      background:
        linear-gradient(135deg, rgba(255, 255, 255, 0.06), transparent 45%),
        linear-gradient(180deg, rgba(20, 25, 37, 0.98), rgba(10, 12, 18, 0.92));
      box-shadow: var(--shadow);
      isolation: isolate;
    }

    .hero::after {
      content: "";
      position: absolute;
      inset: auto -6rem -7rem auto;
      width: 18rem;
      height: 18rem;
      border-radius: 50%;
      background: radial-gradient(circle, rgba(229, 196, 118, 0.2), transparent 70%);
      z-index: -1;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.35rem 0.8rem;
      border: 1px solid rgba(229, 196, 118, 0.3);
      border-radius: 999px;
      background: rgba(229, 196, 118, 0.08);
      color: var(--accent);
      font-size: 0.88rem;
      font-weight: 600;
      letter-spacing: 0.02em;
    }

    .hero__grid {
      display: grid;
      grid-template-columns: minmax(0, 1.3fr) minmax(16rem, 0.9fr);
      gap: 1.5rem;
      align-items: end;
      margin-top: 1rem;
    }

    .hero h1 {
      margin: 0;
      font-size: clamp(2.5rem, 7vw, 4.8rem);
      line-height: 0.98;
      letter-spacing: -0.05em;
      max-width: 10ch;
    }

    .hero__lede {
      margin: 1rem 0 0;
      max-width: 34rem;
      color: var(--muted);
      font-size: 1.08rem;
    }

    .hero__actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.9rem;
      margin-top: 1.5rem;
    }

    .button,
    .button--secondary {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.5rem;
      min-height: 2.9rem;
      padding: 0.8rem 1.15rem;
      border-radius: 999px;
      border: 1px solid transparent;
      font-weight: 700;
      text-align: center;
      transition: transform 0.2s ease, background-color 0.2s ease, border-color 0.2s ease;
    }

    .button {
      background: linear-gradient(180deg, var(--accent-strong), var(--accent));
      color: #121316;
    }

    .button:hover,
    .button--secondary:hover,
    .product-card__button:hover {
      text-decoration: none;
      transform: translateY(-1px);
    }

    .button--secondary {
      border-color: var(--border);
      background: rgba(255, 255, 255, 0.04);
      color: var(--text);
    }

    .hero-stats {
      display: grid;
      gap: 0.9rem;
      padding: 1.2rem;
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      background: rgba(255, 255, 255, 0.03);
    }

    .hero-stats li {
      display: grid;
      gap: 0.15rem;
    }

    .hero-stats strong {
      font-size: 1.8rem;
      color: var(--accent-strong);
      line-height: 1;
    }

    .hero-stats span {
      color: var(--muted);
    }

    .section-heading {
      display: flex;
      flex-wrap: wrap;
      align-items: end;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1rem;
    }

    .section-heading h2 {
      margin: 0;
      font-size: clamp(1.6rem, 4vw, 2.2rem);
      line-height: 1.1;
    }

    .section-heading p {
      margin: 0;
      max-width: 34rem;
      color: var(--muted);
    }

    .pill-list {
      display: flex;
      flex-wrap: wrap;
      gap: 0.55rem;
      margin-top: 1rem;
    }

    .pill-list li {
      padding: 0.45rem 0.8rem;
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.04);
      color: var(--muted);
      font-size: 0.95rem;
    }

    .card-grid,
    .editorial-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }

    .product-card,
    .editorial-card,
    .deal-card {
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      background: var(--bg-panel);
      box-shadow: var(--shadow);
    }

    .product-card {
      display: grid;
      gap: 1rem;
      padding: 1rem;
    }

    .product-card__image {
      aspect-ratio: 4 / 5;
      overflow: hidden;
      border-radius: calc(var(--radius-md) - 0.2rem);
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.09), rgba(255, 255, 255, 0.02));
    }

    .product-card__image img {
      height: 100%;
      object-fit: cover;
    }

    .product-card__body {
      display: grid;
      gap: 0.65rem;
    }

    .product-card__meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 0.75rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .product-card h3,
    .editorial-card h3,
    .deal-card h3 {
      margin: 0;
      font-size: 1.24rem;
      line-height: 1.2;
    }

    .product-card p,
    .editorial-card p,
    .deal-card p {
      margin: 0;
      color: var(--muted);
    }

    .product-card__pricing {
      display: flex;
      align-items: baseline;
      gap: 0.55rem;
      flex-wrap: wrap;
    }

    .product-card__pricing strong {
      font-size: 1.3rem;
    }

    .product-card__pricing s {
      color: var(--soft);
    }

    .product-card__actions {
      display: flex;
      gap: 0.75rem;
      flex-wrap: wrap;
    }

    .product-card__button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 2.8rem;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      border: 1px solid var(--border);
      background: rgba(255, 255, 255, 0.05);
      color: var(--text);
      font-weight: 700;
      text-align: center;
    }

    .product-card__button--primary {
      background: rgba(229, 196, 118, 0.14);
      border-color: rgba(229, 196, 118, 0.3);
      color: var(--accent-strong);
    }

    .deal-list {
      display: grid;
      gap: 1rem;
    }

    .deal-card {
      display: grid;
      grid-template-columns: minmax(0, 1.1fr) auto;
      align-items: center;
      gap: 1rem;
      padding: 1rem 1.1rem;
    }

    .deal-card__badge {
      display: inline-block;
      margin-bottom: 0.5rem;
      color: var(--success);
      font-weight: 700;
      font-size: 0.92rem;
    }

    .deal-card__cta {
      min-width: 10rem;
      justify-self: end;
    }

    .editorial-card {
      overflow: hidden;
    }

    .editorial-card__image {
      aspect-ratio: 16 / 10;
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.09), rgba(255, 255, 255, 0.02));
    }

    .editorial-card__content {
      padding: 1rem;
      display: grid;
      gap: 0.8rem;
    }

    .editorial-card__meta {
      color: var(--accent-strong);
      font-size: 0.9rem;
      font-weight: 700;
      letter-spacing: 0.02em;
    }

    .site-footer {
      border-top: 1px solid rgba(255, 255, 255, 0.08);
      background: rgba(5, 6, 10, 0.85);
    }

    .site-footer__inner {
      display: grid;
      gap: 1rem;
      padding: 1.5rem 0 2rem;
    }

    .site-footer__meta {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: 1rem;
      color: var(--muted);
    }

    .footer-nav ul {
      display: flex;
      flex-wrap: wrap;
      gap: 1rem;
    }

    .service-list {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 0.75rem;
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .service-list li {
      padding: 1rem;
      border: 1px solid var(--border);
      border-radius: var(--radius-sm);
      background: rgba(255, 255, 255, 0.03);
    }

    .service-list strong,
    .service-list span {
      display: block;
    }

    .service-list strong {
      margin-bottom: 0.25rem;
      color: var(--text);
    }

    .service-list span {
      color: var(--muted);
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0 0 0 0);
      clip-path: inset(50%);
      white-space: nowrap;
      border: 0;
    }

    @media (max-width: 60rem) {
      .hero__grid,
      .deal-card {
        grid-template-columns: 1fr;
      }

      .deal-card__cta {
        justify-self: start;
      }

      .card-grid,
      .editorial-grid,
      .service-list {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }
    }

    @media (max-width: 42rem) {
      .site-header__inner {
        flex-direction: column;
        align-items: stretch;
      }

      .top-nav ul,
      .footer-nav ul {
        justify-content: flex-start;
      }

      .card-grid,
      .editorial-grid,
      .service-list {
        grid-template-columns: 1fr;
      }

      .hero h1 {
        max-width: 12ch;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      html {
        scroll-behavior: auto;
      }

      *,
      *::before,
      *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --bg-elevated: Canvas;
        --bg-panel: Canvas;
        --border: CanvasText;
        --border-strong: Highlight;
        --text: CanvasText;
        --muted: CanvasText;
        --soft: GrayText;
        --accent: Highlight;
        --accent-strong: Highlight;
      }

      body,
      .hero,
      .product-card,
      .editorial-card,
      .deal-card,
      .site-header,
      .site-footer,
      .hero-stats,
      .pill-list li {
        forced-color-adjust: auto;
      }

      .button,
      .button--secondary,
      .product-card__button {
        border: 1px solid ButtonText;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>
  <div id="app"></div>
  <script>
    const createPoster = ({ width, height, title, subtitle, tones, accent }) => {
      const svg = `
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}">
          <defs>
            <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
              <stop offset="0%" stop-color="${tones[0]}"/>
              <stop offset="100%" stop-color="${tones[1]}"/>
            </linearGradient>
            <linearGradient id="shine" x1="0" y1="0" x2="1" y2="1">
              <stop offset="0%" stop-color="rgba(255,255,255,0.28)"/>
              <stop offset="100%" stop-color="rgba(255,255,255,0)"/>
            </linearGradient>
          </defs>
          <rect width="${width}" height="${height}" fill="url(#bg)"/>
          <circle cx="${width * 0.8}" cy="${height * 0.2}" r="${Math.min(width, height) * 0.18}" fill="${accent}" opacity="0.28"/>
          <rect x="${width * 0.1}" y="${height * 0.12}" width="${width * 0.8}" height="${height * 0.76}" rx="${width * 0.06}" fill="rgba(8,10,16,0.34)" stroke="rgba(255,255,255,0.14)"/>
          <rect x="${width * 0.15}" y="${height * 0.18}" width="${width * 0.26}" height="${height * 0.46}" rx="${width * 0.13}" fill="rgba(255,255,255,0.12)"/>
          <path d="M ${width * 0.18} ${height * 0.5} C ${width * 0.35} ${height * 0.28}, ${width * 0.48} ${height * 0.7}, ${width * 0.75} ${height * 0.36}" stroke="rgba(255,255,255,0.18)" stroke-width="${Math.max(width * 0.01, 6)}" fill="none"/>
          <rect width="${width}" height="${height}" fill="url(#shine)"/>
          <text x="${width * 0.1}" y="${height * 0.79}" fill="#f5f7fb" font-family="Inter,Segoe UI,Arial,sans-serif" font-size="${Math.round(width * 0.08)}" font-weight="700">${title}</text>
          <text x="${width * 0.1}" y="${height * 0.87}" fill="#d4d8e4" font-family="Inter,Segoe UI,Arial,sans-serif" font-size="${Math.round(width * 0.034)}">${subtitle}</text>
        </svg>
      `;

      return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
    };

    const featuredProducts = [
      {
        id: "product-noir-weekender",
        name: "Noir Weekender",
        category: "Travel Edit",
        price: "$248",
        compareAt: "$310",
        image: createPoster({
          width: 800,
          height: 1000,
          title: "Noir",
          subtitle: "Weekender",
          tones: ["#1a2130", "#07090d"],
          accent: "#e5c476"
        }),
        alt: "Stylized product poster for the Noir Weekender bag in black and gold tones"
      },
      {
        id: "product-lumen-knit-coat",
        name: "Lumen Knit Coat",
        category: "Outerwear",
        price: "$184",
        compareAt: "$230",
        image: createPoster({
          width: 800,
          height: 1000,
          title: "Lumen",
          subtitle: "Knit Coat",
          tones: ["#313440", "#0d1018"],
          accent: "#9ca9d7"
        }),
        alt: "Stylized product poster for the Lumen Knit Coat in charcoal and steel blue tones"
      },
      {
        id: "product-aura-table-lamp",
        name: "Aura Table Lamp",
        category: "Home Objects",
        price: "$96",
        compareAt: "$120",
        image: createPoster({
          width: 800,
