          title: "Aura",
          subtitle: "Table Lamp",
          tones: ["#4b3524", "#08090d"],
          accent: "#f0d28d"
        }),
        alt: "Stylized product poster for the Aura Table Lamp with warm amber lighting"
      }
    ];

    const deals = [
      {
        id: "midnight-members-event",
        title: "Midnight Members Event",
        description: "Take 25% off elevated essentials and unlock early access to limited capsule drops through Sunday.",
        label: "Exclusive savings",
        action: "Shop member prices"
      },
      {
        id: "delivery-details",
        title: "Complimentary delivery over $150",
        description: "Build a full-room edit or finish your travel wardrobe with shipping covered on qualifying orders.",
        label: "Always-on benefit",
        action: "View delivery details"
      }
    ];

    const editorialStories = [
      {
        id: "story-moody-living-space",
        category: "Journal",
        title: "How to build a moody living space with three anchoring pieces",
        description: "A room-by-room guide to layering rich textures, warm light, and sculptural accents without visual clutter.",
        image: createPoster({
          width: 1200,
          height: 750,
          title: "Moody Living",
          subtitle: "Journal story",
          tones: ["#473424", "#0d1018"],
          accent: "#e5c476"
        }),
        alt: "Editorial illustration for a moody living space story with amber lighting and a dark interior palette"
      },
      {
        id: "story-evening-uniform",
        category: "Style Notes",
        title: "The evening uniform: five pieces that carry every after-hours plan",
        description: "From dinner reservations to rooftop sets, this edit balances polish, comfort, and repeat wear.",
        image: createPoster({
          width: 1200,
          height: 750,
          title: "Evening Uniform",
          subtitle: "Style notes",
          tones: ["#22253a", "#090b11"],
          accent: "#9ca9d7"
        }),
        alt: "Editorial illustration for an evening style story in midnight blue and charcoal tones"
      },
      {
        id: "story-gift-guide",
        category: "Gift Guide",
        title: "Curated gestures for hosts, frequent flyers, and design obsessives",
        description: "Thoughtful picks that feel personal, useful, and worth keeping in sight long after they are opened.",
        image: createPoster({
          width: 1200,
          height: 750,
          title: "Gift Guide",
          subtitle: "Curated gestures",
          tones: ["#3f2d31", "#0a0b10"],
          accent: "#d49eb2"
        }),
        alt: "Editorial illustration for a gift guide with jewel-toned accents on a dark background"
      }
    ];

    const navItems = [
      { label: "New arrivals", href: "#featured-products", current: true },
      { label: "Deals", href: "#latest-deals" },
      { label: "Editorial", href: "#editorial-content" },
      { label: "Stores", href: "#stores" }
    ];

    const footerLinks = [
      { label: "Client services", href: "#client-services" },
      { label: "Shipping & returns", href: "#shipping-returns" },
      { label: "Gift cards", href: "#gift-cards" },
      { label: "Contact", href: "#contact" }
    ];

    const serviceNotes = [
      { id: "client-services", title: "Client services", detail: "Concierge styling support available daily." },
      { id: "shipping-returns", title: "Shipping & returns", detail: "Free returns within 30 days on eligible items." },
      { id: "gift-cards", title: "Gift cards", detail: "Digital delivery in minutes with custom notes." },
      { id: "contact", title: "Contact", detail: "Reach the atelier team at hello@nightfall.example." }
    ];

    const stats = [
      { value: "72h", label: "New capsule arrivals refreshed every three days" },
      { value: "4.9/5", label: "Average client rating across our signature edits" },
      { value: "150+", label: "Design-led pieces curated for home, travel, and wardrobe" }
    ];

    const shopTags = ["Elevated basics", "Soft tailoring", "Objects for home", "Weekend travel", "Host gifts"];

    const Header = () => `
      <header class="site-header">
        <div class="site-header__inner">
          <a class="brand" href="#" aria-label="Nightfall Atelier home">
            <span class="brand__mark" aria-hidden="true"><span>N</span></span>
