                </li>
              `).join("")}
            </ul>
          </nav>
        </div>
      </header>
    `;

    const Hero = () => `
      <section class="hero" aria-labelledby="hero-title">
        <span class="eyebrow">Fall Preview 2026</span>
        <div class="hero__grid">
          <div>
            <h1 id="hero-title">Retail design for after dark.</h1>
            <p class="hero__lede">
