            </ul>
          </div>
          <ul class="hero-stats" aria-label="Brand highlights">
            ${stats.map((item) => `
              <li>
                <strong>${item.value}</strong>
                <span>${item.label}</span>
              </li>
            `).join("")}
          </ul>
        </div>
      </section>
    `;

    const ProductCard = (product) => `
      <li>
        <article class="product-card" id="${product.id}">
          <div class="product-card__image">
            <img src="${product.image}" alt="${product.alt}">
          </div>
          <div class="product-card__body">
            <div class="product-card__meta">
              <span>${product.category}</span>
              <span>Limited run</span>
            </div>
            <a href="#${product.id}">
              <h3>${product.name}</h3>
            </a>
            <p>Designed to transition from weekday errands to evening plans without losing shape or polish.</p>
            <div class="product-card__pricing" aria-label="Price ${product.price}, previously ${product.compareAt}">
              <strong>${product.price}</strong>
              <s>${product.compareAt}</s>
            </div>
            <div class="product-card__actions">
              <button
                class="product-card__button product-card__button--primary"
                type="button"
                data-add-to-bag="${product.name}"
                aria-label="Add to bag: ${product.name}"
              >
                Add to bag
              </button>
              <a class="product-card__button" href="#${product.id}">View details</a>
            </div>
          </div>
        </article>
      </li>
    `;

    const FeaturedSection = () => `
      <section class="section" id="featured-products" aria-labelledby="featured-products-heading">
        <div class="section-heading">
          <div>
            <h2 id="featured-products-heading">Featured products</h2>
            <p>New statement pieces selected for versatility, tactile finish, and a gallery-like presentation at home or on the move.</p>
          </div>
        </div>
        <ul class="card-grid">
          ${featuredProducts.map(ProductCard).join("")}
        </ul>
      </section>
    `;

    const DealCard = (deal) => `
      <li>
        <article class="deal-card" id="${deal.id}">
          <div>
            <span class="deal-card__badge">${deal.label}</span>
            <h3>${deal.title}</h3>
            <p>${deal.description}</p>
          </div>
          <a class="button deal-card__cta" href="#${deal.id}">${deal.action}</a>
        </article>
      </li>
    `;

    const DealsSection = () => `
      <section class="section" id="latest-deals" aria-labelledby="latest-deals-heading">
        <div class="section-heading">
