        }),
        alt: "Stylized product poster for the Noir Weekender bag in black and gold tones"
      },
      {
        id: "product-lumen-knit-coat",
        name: "Lumen Knit Coat",
        category: "Outerwear",
        price: "$184",
        compareAt: "$230",
        image: createPoster({
          width: 800,
          height: 1000,
          title: "Lumen",
