    `;

    const EditorialCard = (story) => `
      <li>
        <article class="editorial-card" id="${story.id}">
          <div class="editorial-card__image">
            <img src="${story.image}" alt="${story.alt}">
          </div>
          <div class="editorial-card__content">
            <span class="editorial-card__meta">${story.category}</span>
